mapper.select:
SELECT EXISTS( select 1 from so_info si
inner join so_detail sod on si.id = sod.main_id
where si.is_deleted = false and sod.is_deleted = false
and si.customer_id = #{customer} and sod.platform_sku_no = #{platformSku}
limit 1
)

select si.approve_status as approveStatus, si.id as sourceId, si.code as sourceCode, sd.id as sourceDetailId, sd.sku_id as skuId, sd.sku_no as skuNo, sd.qty, si.warehouse_id as warehouseId from so_info si left join so_detail sd on si.id = sd.main_id and sd.is_deleted = false
si.is_deleted = false and sd.is_close = false and si.id in
#{item}

SELECT si.code AS soCode, si.warehouse_org_id AS inventoryOrgId, si.customer_id, si.require_date, si.warehouse_id, sd.id AS detailId, sd.main_id AS soId, sd.sku_id, sd.sku_no, sd.platform_sku_no, sd.is_close, sd.qty AS salesQty, (select COALESCE(sum(sdnd.delivery_qty),0) from so_delivery_notice sdn inner join so_delivery_notice_detail sdnd on sdn.id = sdnd.main_id and sdnd.is_deleted = false where sdn.is_deleted = false and sdn.invalid_status = false and sdnd.source_detail_id = sd.id) as alreadyDeliveryQty, sd.remark FROM so_info si LEFT JOIN so_detail sd ON si.id = sd.main_id AND si.is_deleted = FALSE WHERE sd.is_deleted = FALSE AND sd.is_close=FALSE
AND sd.id IN
#{id}

SELECT si.code AS soCode, si.customer_id, sd.id AS detailId, sd.main_id AS soId, sd.sku_id, sd.sku_no, sd.qty AS salesQty, si.currency, si.currency_symbol, sd.amount, sd.tax_amount, sd.exchange_rate, si.sales_org_id, si.warehouse_org_id as warehouseOrgId FROM so_info si LEFT JOIN so_detail sd ON si.id = sd.main_id AND si.is_deleted = FALSE WHERE sd.is_deleted = FALSE AND sd.is_close=FALSE
AND sd.id IN
#{detailId}

SELECT DISTINCT so.* FROM so_info so
LEFT JOIN so_detail sod ON so.id = sod.main_id
WHERE so.bill_date >= #{startDate}
AND so.bill_date <= #{endDate}
AND so.approve_status = 'approve'
AND so.is_deleted = FALSE
AND sod.is_deleted = FALSE
LIMIT #{pageSize} OFFSET #{offset}
